<template>
  <section class="panel">
    <div class="panel-head"><div><h2>公司組</h2><p>香港／澳門公司、內地公司與所屬牌照。</p></div><div class="heading-actions"><button class="button" @click="dialog = 'new-group'; dialogForm = { name: '', notes: '' }">＋ 新增公司組</button><button class="button primary" @click="newCompany">＋ 新增公司</button></div></div>
    <div v-if="!groups.length" class="empty">尚未建立公司組</div>
    <div v-for="group in groups" :key="group.id" class="company-group-block">
      <div class="panel-head"><div><h3>{{ group.name }}</h3><p>{{ group.notes || '尚未填寫公司組備註' }}</p></div><button class="button" @click="dialog = 'group'; dialogForm = { ...group }">編輯公司組</button></div>
      <div v-if="group.warnings?.length" class="status-warnings"><span v-for="warning in group.warnings" :key="warning" class="warning">{{ warning }}</span></div>
      <div class="table-wrap"><table><thead><tr><th>香港／澳門公司</th><th>內地公司</th><th>牌照</th><th>狀態標籤</th></tr></thead><tbody><tr><td>{{ foreignCompanies(group).map(item => item.name).join('、') || '未登記' }}</td><td>{{ mainlandCompanies(group).map(item => item.name).join('、') || '未登記' }}</td><td>{{ group.plates.length }} 個牌照</td><td>{{ group.warnings?.join('、') || '正常' }}</td></tr></tbody></table></div>
      <div class="company-columns"><div><h3>香港／澳門公司</h3><div v-for="company in foreignCompanies(group)" :key="company.id" class="company-card" :class="companyCardClass(company)"><div class="company-card-title"><strong>{{ company.jurisdiction }} · {{ company.name }}</strong><span class="company-status" :class="statusClass(company.status)">{{ company.status }}</span></div><span>{{ company.jurisdiction === '香港' ? '商業登記號碼（BR）' : '商業登記編號' }}：{{ company.registration_no || '—' }}</span><span v-if="company.jurisdiction === '香港'">公司編號（CR）：{{ company.company_number || '—' }}</span><span>成立日期：{{ company.incorporated_on || '—' }}</span><template v-if="company.jurisdiction === '香港'"><label class="inline-date">{{ company.brExpiresOn ? `BR 到期：${company.brExpiresOn}` : 'BR 到期待錄入' }}<input v-model="brDates[company.id]" type="date" aria-label="BR 到期日" /></label><button class="button" @click="saveBr(company)">儲存 BR 日期</button><span>下一次周年申報（NAR1）：{{ company.nar1DueOn || '成立日期待錄入' }}</span></template><div class="company-card-actions"><button class="button" @click="editCompany(company)">編輯</button><ExpiryPanel owner-type="company" :owner-id="company.id" @saved="saved" @error="emit('error', $event)" /></div></div></div>
      <div><h3>內地公司</h3><div v-for="company in mainlandCompanies(group)" :key="company.id" class="company-card" :class="companyCardClass(company)"><div class="company-card-title"><strong>內地 · {{ company.name }}</strong><span class="company-status" :class="statusClass(company.status)">{{ company.status }}</span></div><span>統一社會信用代碼：{{ company.registration_no || '—' }}</span><span>成立日期：{{ company.incorporated_on || '—' }}</span><span>納稅人類型：{{ company.taxpayer_type || '—' }}</span><div class="company-card-actions"><button class="button" @click="editCompany(company)">編輯</button><ExpiryPanel owner-type="company" :owner-id="company.id" @saved="saved" @error="emit('error', $event)" /></div></div></div></div>
      <div class="group-plates"><h3>所屬兩地牌</h3><div v-for="plate in group.plates" :key="plate.id" class="record-row"><button class="phase-link" @click="emit('plate', plate.id)">{{ plate.mainland_plate || '內地車牌待補' }} · {{ plate.local_plate || '港澳車牌待補' }}</button><span>{{ plate.route }} · 口岸：{{ plate.port || '待設定' }}</span><span>{{ plate.usage_status }}</span></div><div v-if="!group.plates.length" class="empty">尚未掛接兩地牌</div></div>
    </div>
    <div v-if="ungrouped.length" class="company-group-block"><h3>未分組公司</h3><div class="company-columns"><div v-for="company in ungrouped" :key="company.id" class="company-card"><strong>{{ company.jurisdiction }} · {{ company.name }}</strong><span>{{ registrationLabel(company.jurisdiction) }}：{{ company.registration_no || '—' }}</span><span v-if="company.jurisdiction === '香港'">公司編號（CR）：{{ company.company_number || '—' }}</span><template v-if="company.jurisdiction === '香港'"><label class="inline-date">{{ company.brExpiresOn ? `BR 到期：${company.brExpiresOn}` : 'BR 到期待錄入' }}<input v-model="brDates[company.id]" type="date" aria-label="BR 到期日" /></label><button class="button" @click="saveBr(company)">儲存 BR 日期</button><span>下一次周年申報（NAR1）：{{ company.nar1DueOn || '成立日期待錄入' }}</span></template><span v-if="company.jurisdiction === '內地'">納稅人類型：{{ company.taxpayer_type || '—' }}</span><span>狀態：{{ company.status }}</span><button class="button" @click="editCompany(company)">編輯</button><ExpiryPanel owner-type="company" :owner-id="company.id" @saved="saved" @error="emit('error', $event)" /></div></div></div>
  </section>
  <div v-if="dialog" class="overlay" @click.self="dialog = null"><div class="dialog"><div class="dialog-head"><div><div class="eyebrow">COMPANY GROUP</div><h2>{{ dialog === 'new-group' ? '新增公司組' : dialog === 'group' ? '編輯公司組' : dialog === 'new-company' ? '新增公司' : '編輯公司' }}</h2></div><button class="close" @click="dialog = null">×</button></div>
    <template v-if="dialog === 'group' || dialog === 'new-group'"><div class="form-grid"><label>公司組名稱<input v-model="dialogForm.name" /></label><label>備註<input v-model="dialogForm.notes" /></label></div><button class="button primary full" @click="saveGroup">儲存公司組</button></template>
    <template v-else><div class="form-grid"><label>公司組<select v-model="dialogForm.groupId"><option value="">未分組</option><option v-for="group in groups" :key="group.id" :value="group.id">{{ group.name }}</option></select></label><label>司法區<select v-model="dialogForm.jurisdiction"><option v-for="jurisdiction in ['香港','澳門','內地']" :key="jurisdiction">{{ jurisdiction }}</option></select></label><label>公司名稱<input v-model="dialogForm.name" /></label><label>{{ registrationLabel(dialogForm.jurisdiction) }}<input v-model="dialogForm.registrationNo" /></label><label v-if="dialogForm.jurisdiction === '香港'">公司編號（CR）<input v-model="dialogForm.companyNumber" /></label><label>成立日期<input v-model="dialogForm.incorporatedOn" type="date" /></label><label v-if="dialogForm.jurisdiction === '內地'">納稅人類型<select v-model="dialogForm.taxpayerType"><option value="">待選擇</option><option>小規模納稅人</option><option>一般納稅人</option></select></label><label>狀態<select v-model="dialogForm.status"><option v-for="status in statuses" :key="status">{{ status }}</option></select></label><label>狀態變更日期<input v-model="dialogForm.statusChangedOn" type="date" /></label><label>備註<input v-model="dialogForm.notes" /></label></div><div v-if="dialogForm.jurisdiction === '香港' && dialog === 'company'" class="lookup-box"><button class="button" :disabled="lookingUp" @click="lookupCompany">{{ lookingUp ? '查詢中…' : '向公司註冊處查詢' }}</button><p v-if="lookupError" class="error">{{ lookupError }}</p><div v-if="lookupResult" class="lookup-result"><strong>{{ lookupResult.name }}</strong><span>BRN：{{ lookupResult.registrationNo }}</span><span>英文名稱：{{ lookupResult.englishName || '—' }}</span><span>成立日期：{{ lookupResult.incorporatedOn || '—' }}</span><span>公司類型：{{ lookupResult.companyType || '—' }}</span><span>註冊地址：{{ lookupResult.address || '—' }}</span><button class="button primary" @click="applyLookup">套用查詢結果</button></div></div><button class="button primary full" @click="saveCompany">儲存公司</button></template>
  </div></div>
</template>
<script setup>
import { ref, computed, watch } from 'vue'
import { api } from '../api'
import ExpiryPanel from '../components/ExpiryPanel.vue'
const props = defineProps({ initialCustomer: String, addGroupRequest: Number })
const emit = defineEmits(['error', 'saved', 'plate'])
const statuses = ['存續', '經營異常', '註銷中', '已註銷']
const groups = ref([]), companies = ref([]), dialog = ref(null), dialogForm = ref({}), brDates = ref({}), lookingUp = ref(false), lookupResult = ref(null), lookupError = ref('')
const ungrouped = computed(() => companies.value.filter(item => !item.group_id))
const foreignCompanies = group => group.companies.filter(item => item.jurisdiction !== '內地')
const mainlandCompanies = group => group.companies.filter(item => item.jurisdiction === '內地')
const statusClass = status => ({ '經營異常': 'warning', '註銷中': 'warning', '已註銷': 'dissolved' }[status] || '')
const companyCardClass = company => company.status === '已註銷' ? 'company-dissolved' : ''
const registrationLabel = jurisdiction => ({ 香港: '商業登記號碼（BR）', 澳門: '商業登記編號', 內地: '統一社會信用代碼' }[jurisdiction] || '登記號碼')
async function load() { if (!props.initialCustomer) return; try { [groups.value, companies.value] = await Promise.all([api(`/company-groups?customerId=${encodeURIComponent(props.initialCustomer)}`), api(`/companies?customerId=${encodeURIComponent(props.initialCustomer)}`)]); brDates.value = Object.fromEntries(companies.value.filter(item => item.jurisdiction === '香港').map(item => [item.id, item.brExpiresOn || ''])) } catch (error) { emit('error', error) } }
function saved(message) { load(); emit('saved', message) }
function newCompany() { dialog.value = 'new-company'; dialogForm.value = { groupId: '', jurisdiction: '香港', name: '', registrationNo: '', companyNumber: '', incorporatedOn: '', taxpayerType: '', status: '存續', statusChangedOn: '', notes: '' } }
function editCompany(company) { dialog.value = 'company'; dialogForm.value = { ...company, groupId: company.group_id || '', registrationNo: company.registration_no || '', companyNumber: company.company_number || '', incorporatedOn: company.incorporated_on || '', taxpayerType: company.taxpayer_type || '', statusChangedOn: company.status_changed_on || '' }; lookupResult.value = null; lookupError.value = '' }
async function saveGroup() { try { const isNew = dialog.value === 'new-group'; await api(isNew ? '/company-groups' : `/company-groups/${dialogForm.value.id}`, isNew ? 'POST' : 'PATCH', { ...dialogForm.value, customerId: props.initialCustomer }); dialog.value = null; saved('公司組已儲存') } catch (error) { emit('error', error) } }
async function saveCompany() { try { const isNew = dialog.value === 'new-company'; await api(isNew ? '/companies' : `/companies/${dialogForm.value.id}`, isNew ? 'POST' : 'PATCH', { ...dialogForm.value, customerId: props.initialCustomer }); dialog.value = null; saved('公司已儲存') } catch (error) { emit('error', error) } }
async function saveBr(company) { try { await api('/tracked-items', 'PUT', { ownerType: 'company', ownerId: company.id, code: 'hk_br', expiresOn: brDates.value[company.id] || '' }); saved('BR 日期已儲存') } catch (error) { emit('error', error) } }
async function lookupCompany() { lookupResult.value = null; lookupError.value = ''; if (!/^\d{8}$/.test(String(dialogForm.value.registrationNo || ''))) { lookupError.value = '請先填寫 8 位商業登記號碼'; return } lookingUp.value = true; try { lookupResult.value = await api(`/companies/${dialogForm.value.id}/hk-lookup`, 'POST') } catch (error) { lookupError.value = error.message } finally { lookingUp.value = false } }
function applyLookup() { if (!lookupResult.value) return; dialogForm.value.name = lookupResult.value.name || dialogForm.value.name; dialogForm.value.incorporatedOn = lookupResult.value.incorporatedOn || dialogForm.value.incorporatedOn }
watch(() => props.initialCustomer, load, { immediate: true })
watch(() => props.addGroupRequest, () => { dialog.value = 'new-group'; dialogForm.value = { name: '', notes: '' } }, { immediate: props.addGroupRequest > 0 })
</script>
